// What: the page's content security policy, one string for dev and production.
// Why: the camera worker needs a blob: worker, and every other origin stays closed.
// Removed: the window could load remote scripts or connect off this machine.
export function contentSecurityPolicy(): string {
  return [
    "default-src 'self'",
    "script-src 'self'",
    "style-src 'self'",
    "img-src 'self'",
    "connect-src 'self'",
    "worker-src 'self' blob:",
    "object-src 'none'",
    "base-uri 'none'",
    "frame-src 'none'",
    "form-action 'none'",
  ].join('; ');
}

import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { describe, it } from 'node:test';
import { contentSecurityPolicy } from './security.js';

describe('contentSecurityPolicy', () => {
  const policy = contentSecurityPolicy();

  it('allows the SDK worker blob and nothing off-origin', () => {
    assert.match(policy, /worker-src 'self' blob:/);
    assert.doesNotMatch(policy, /unsafe-inline|unsafe-eval|https:|127\.0\.0\.1/);
    assert.match(policy, /default-src 'self'/);
    assert.match(policy, /connect-src 'self'/);
  });

  it('is the policy the renderer document is built with', () => {
    const html = readFileSync(new URL('../../src/renderer/index.html', import.meta.url), 'utf8');
    assert.match(html, /__CHESSPULSE_CSP__/);
  });
});

// What: decides whether a page may open the camera.
// Why: consent and the page origin are checked in the main process, so the page cannot skip them.
// Removed: a remote document, a subframe, or a microphone request could receive media.
const LOOPBACK_HOSTS = new Set(['127.0.0.1', 'localhost']);

export interface MediaPermissionInput {
  permission: string;
  requestingUrl: string | undefined;
  consentGranted: boolean;
  devUrl: string | undefined;
  isMainFrame: boolean;
  mediaTypes?: readonly string[];
  mediaType?: string;
}

export function grantsMediaPermission(input: MediaPermissionInput): boolean {
  if (input.permission !== 'media') return false;
  if (!input.consentGranted || !input.isMainFrame) return false;
  if (!isVideoOnly(input.mediaTypes, input.mediaType)) return false;
  if (!input.requestingUrl) return false;
  return isLocalPage(input.requestingUrl, input.devUrl);
}

function isVideoOnly(mediaTypes: readonly string[] | undefined, mediaType: string | undefined): boolean {
  if (mediaTypes) return mediaTypes.length > 0 && mediaTypes.every((type) => type === 'video');
  return mediaType === 'video';
}

function isLocalPage(requestingUrl: string, devUrl: string | undefined): boolean {
  let page: URL;
  try {
    page = new URL(requestingUrl);
  } catch {
    return false;
  }
  if (page.protocol === 'file:') return true;
  if (!devUrl) return false;
  let dev: URL;
  try {
    dev = new URL(devUrl);
  } catch {
    return false;
  }
  if (dev.protocol !== 'http:' && dev.protocol !== 'https:') return false;
  if (!LOOPBACK_HOSTS.has(dev.hostname)) return false;
  return page.origin === dev.origin;
}

import assert from 'node:assert/strict';
import { describe, it } from 'node:test';
import { grantsMediaPermission, type MediaPermissionInput } from './permission.js';

const devUrl = 'http://127.0.0.1:5173';

function request(overrides: Partial<MediaPermissionInput> = {}): MediaPermissionInput {
  return {
    permission: 'media',
    requestingUrl: 'file:///tmp/chesspulse/index.html',
    consentGranted: true,
    devUrl,
    isMainFrame: true,
    mediaTypes: ['video'],
    ...overrides,
  };
}

describe('grantsMediaPermission', () => {
  it('allows the camera on a local file after consent', () => {
    assert.equal(grantsMediaPermission(request()), true);
  });

  it('denies the camera when consent is absent', () => {
    assert.equal(grantsMediaPermission(request({ consentGranted: false })), false);
  });

  it('allows the pinned loopback dev page and not a lookalike port', () => {
    assert.equal(
      grantsMediaPermission(request({ requestingUrl: 'http://127.0.0.1:5173/' })),
      true,
    );
    assert.equal(
      grantsMediaPermission(request({ requestingUrl: 'http://127.0.0.1:51730/' })),
      false,
    );
  });

  it('denies a remote page even when the dev URL was pointed at it', () => {
    assert.equal(
      grantsMediaPermission(
        request({
          requestingUrl: 'https://example.com/',
          devUrl: 'https://example.com',
        }),
      ),
      false,
    );
  });

  it('denies microphone, screen capture, and subframe requests', () => {
    assert.equal(grantsMediaPermission(request({ mediaTypes: ['video', 'audio'] })), false);
    assert.equal(grantsMediaPermission(request({ mediaTypes: undefined, mediaType: 'audio' })), false);
    assert.equal(grantsMediaPermission(request({ permission: 'display-capture' })), false);
    assert.equal(grantsMediaPermission(request({ isMainFrame: false })), false);
  });
});

