// What: the isolated preload. It exposes one consent call and nothing else.
// Why: the page must not receive Node, files, or keys, and main checks the payload again.
// Removed: a later screen could not tell the desktop process that consent changed.
import { contextBridge, ipcRenderer } from 'electron';

const CONSENT_CHANNEL = 'cp:consent:set';

contextBridge.exposeInMainWorld('chesspulse', {
  setConsent(granted: unknown): Promise<boolean> {
    if (typeof granted !== 'boolean') {
      return Promise.reject(new Error('Consent was not a yes or no.'));
    }
    return ipcRenderer.invoke(CONSENT_CHANNEL, { granted }).then((value: unknown) => {
      if (typeof value !== 'object' || value === null || !('granted' in value)) {
        throw new Error('The window returned an unexpected consent state.');
      }
      const state = value.granted;
      if (typeof state !== 'boolean') {
        throw new Error('The window returned an unexpected consent state.');
      }
      return state;
    });
  },
});

import { useState } from 'react';
import './bridge';

export function App() {
  const [granted, setGranted] = useState(false);
  const [note, setNote] = useState('The camera stays off until you consent.');

  async function onConsent(): Promise<void> {
    const bridge = window.chesspulse;
    if (!bridge) {
      setNote('This page is open outside the ChessPulse window. The camera stays off.');
      return;
    }
    try {
      const next = await bridge.setConsent(!granted);
      setGranted(next);
      setNote(
        next
          ? 'The camera is allowed for this window. Sensing has not started.'
          : 'The camera stays off until you consent.',
      );
    } catch {
      setNote('Consent could not be saved. The camera state is unchanged.');
    }
  }

  return (
    <main>
      <p className="label">ChessPulse</p>
      <h1>Sensing has not started.</h1>
      <p aria-live="polite">{note}</p>
      <button type="button" aria-pressed={granted} onClick={() => void onConsent()}>
        {granted ? 'Revoke camera consent' : 'Allow the camera'}
      </button>
    </main>
  );
}

