// What: the isolated preload. It exposes one consent call and nothing else.
// Why: the page must not receive Node, files, or keys, and main checks the payload again.
// Removed: a later screen could not tell the desktop process that consent changed.
import { contextBridge, ipcRenderer } from 'electron';

const CONSENT_CHANNEL = 'cp:consent:set';

interface ConsentState {
  granted: boolean;
  cameraAllowed: boolean;
}

function readConsentState(value: unknown): ConsentState {
  if (typeof value !== 'object' || value === null) {
    throw new Error('The window returned an unexpected consent state.');
  }
  const record = value as { granted?: unknown; cameraAllowed?: unknown };
  if (typeof record.granted !== 'boolean' || typeof record.cameraAllowed !== 'boolean') {
    throw new Error('The window returned an unexpected consent state.');
  }
  return { granted: record.granted, cameraAllowed: record.cameraAllowed };
}

contextBridge.exposeInMainWorld('chesspulse', {
  setConsent(granted: unknown): Promise<ConsentState> {
    if (typeof granted !== 'boolean') {
      return Promise.reject(new Error('Consent was not a yes or no.'));
    }
    return ipcRenderer.invoke(CONSENT_CHANNEL, { granted }).then(readConsentState);
  },
});

// What: the typed surface the page may call across the preload.
// Why: the renderer has no Node, and the main process checks every argument again.
// Removed: a screen could not tell the desktop process that consent changed.
export interface ConsentState {
  granted: boolean;
  cameraAllowed: boolean;
}

export interface ChessPulseBridge {
  setConsent(granted: boolean): Promise<ConsentState>;
}

declare global {
  interface Window {
    chesspulse?: ChessPulseBridge;
  }
}

import { useState } from 'react';

function consentNote(granted: boolean, cameraAllowed: boolean): string {
  if (!granted) return 'The camera stays off until you consent.';
  if (!cameraAllowed) {
    return 'Consent is on. This page is not a local file, so the camera stays blocked.';
  }
  return 'The camera is allowed for this window. Sensing has not started.';
}

export function App() {
  const [granted, setGranted] = useState(false);
  const [note, setNote] = useState(consentNote(false, false));

  async function onConsent(): Promise<void> {
    const bridge = window.chesspulse;
    if (!bridge) {
      setNote('This page is open outside the ChessPulse window. The camera stays off.');
      return;
    }
    try {
      const next = await bridge.setConsent(!granted);
      setGranted(next.granted);
      setNote(consentNote(next.granted, next.cameraAllowed));
    } catch {
      setNote('Consent could not be saved. The camera state is unchanged.');
    }
  }

  return (
    <main>
      <p className="label">ChessPulse</p>
      <h1>Sensing has not started.</h1>
      <p aria-live="polite">{note}</p>
      <button type="button" aria-pressed={granted} onClick={() => void onConsent()}>
        {granted ? 'Revoke camera consent' : 'Allow the camera'}
      </button>
    </main>
  );
}

// What: stores the explicit consent flag and answers the page on one channel.
// Why: the camera permission handler reads this flag, and the page cannot set it by any other path.
// Removed: revoking consent would not reach the process that grants the camera.
import { ipcMain } from 'electron';
import { consentRequestSchema, consentStateSchema } from '../shared/contracts.js';
import { grantsMediaPermission } from './permission.js';

const CONSENT_CHANNEL = 'cp:consent:set';

let consentGranted = false;

export function currentConsent(): boolean {
  return consentGranted;
}

export function registerConsentHandler(): void {
  ipcMain.handle(CONSENT_CHANNEL, (event, payload: unknown) => {
    const parsed = consentRequestSchema.safeParse(payload);
    if (!parsed.success) throw new Error('Consent was not a yes or no.');
    consentGranted = parsed.data.granted;
    return consentStateSchema.parse({
      granted: consentGranted,
      cameraAllowed: grantsMediaPermission({
        permission: 'media',
        requestingUrl: event.senderFrame?.url,
        consentGranted,
        isMainFrame: true,
        mediaTypes: ['video'],
      }),
    });
  });
}

